# -*- coding: utf-8 -*-
"""
飞书(Feishu)通知工具
支持：Webhook消息、API调用
"""
import os
import sys
import json
import urllib.request
import urllib.error
from datetime import datetime
from pathlib import Path

def load_env():
    """加载环境变量"""
    env_file = Path.home() / ".config/feishu/.env"
    if env_file.exists():
        with open(env_file) as f:
            for line in f:
                line = line.strip()
                if line and not line.startswith("#") and "=" in line:
                    key, value = line.split("=", 1)
                    os.environ.setdefault(key, value)

def send_webhook(message: str, title: str = None, msg_type: str = "text"):
    """通过Webhook发送消息"""
    webhook_url = os.getenv("FEISHU_WEBHOOK_URL")
    if not webhook_url:
        print("错误：未配置 FEISHU_WEBHOOK_URL")
        return False

    # 构建消息体
    if msg_type == "text":
        payload = {"msg_type": "text", "content": {"text": message}}
    elif msg_type == "markdown":
        payload = {
            "msg_type": "interactive",
            "card": {
                "header": {"title": {"tag": "plain_text", "content": title or "通知"}},
                "elements": [{"tag": "div", "text": {"tag": "lark_md", "content": message}}]
            }
        }
    else:
        payload = {"msg_type": "text", "content": {"text": message}}

    try:
        req = urllib.request.Request(
            webhook_url,
            data=json.dumps(payload).encode("utf-8"),
            headers={"Content-Type": "application/json"},
            method="POST"
        )
        with urllib.request.urlopen(req, timeout=30) as response:
            result = json.loads(response.read().decode("utf-8"))
            if result.get("code") == 0:
                print(f"✅ 消息发送成功")
                return True
            else:
                print(f"❌ 发送失败: {result.get('msg')}")
                return False
    except Exception as e:
        print(f"❌ 发送失败: {e}")
        return False

def get_tenant_access_token():
    """获取租户访问令牌"""
    app_id = os.getenv("FEISHU_APP_ID")
    app_secret = os.getenv("FEISHU_APP_SECRET")

    if not app_id or not app_secret:
        print("错误：未配置 FEISHU_APP_ID 或 FEISHU_APP_SECRET")
        return None

    url = "https://open.feishu.cn/open-apis/auth/v3/tenant_access_token/internal"
    payload = {"app_id": app_id, "app_secret": app_secret}

    try:
        req = urllib.request.Request(
            url,
            data=json.dumps(payload).encode("utf-8"),
            headers={"Content-Type": "application/json"},
            method="POST"
        )
        with urllib.request.urlopen(req, timeout=30) as response:
            result = json.loads(response.read().decode("utf-8"))
            if result.get("code") == 0:
                return result.get("tenant_access_token")
            else:
                print(f"获取token失败: {result.get('msg')}")
                return None
    except Exception as e:
        print(f"获取token失败: {e}")
        return None

def send_to_chat(chat_id: str, message: str, token: str = None):
    """通过API发送消息到指定聊天"""
    if not token:
        token = get_tenant_access_token()
        if not token:
            return False

    url = f"https://open.feishu.cn/open-apis/im/v1/messages?receive_id_type=chat_id"
    payload = {
        "receive_id": chat_id,
        "msg_type": "text",
        "content": json.dumps({"text": message})
    }

    try:
        req = urllib.request.Request(
            url,
            data=json.dumps(payload).encode("utf-8"),
            headers={
                "Content-Type": "application/json",
                "Authorization": f"Bearer {token}"
            },
            method="POST"
        )
        with urllib.request.urlopen(req, timeout=30) as response:
            result = json.loads(response.read().decode("utf-8"))
            if result.get("code") == 0:
                print(f"✅ 消息发送成功")
                return True
            else:
                print(f"❌ 发送失败: {result.get('msg')}")
                return False
    except Exception as e:
        print(f"❌ 发送失败: {e}")
        return False

def main():
    load_env()

    if len(sys.argv) < 2:
        print("""用法: feishu-notify <命令> [参数]

命令:
  webhook <消息> [标题]     通过Webhook发送文本消息
  markdown <内容> [标题]    通过Webhook发送Markdown卡片
  api <chat_id> <消息>      通过API发送到指定群组

示例:
  feishu-notify webhook "部署成功！"
  feishu-notify markdown "## 每日新闻\\n- 新闻1\\n- 新闻2" "医疗新闻日报"
  feishu-notify api "oc_xxxxx" "测试消息"
""")
        sys.exit(1)

    command = sys.argv[1]

    if command == "webhook":
        message = sys.argv[2] if len(sys.argv) > 2 else "测试消息"
        title = sys.argv[3] if len(sys.argv) > 3 else None
        success = send_webhook(message, title, "text")
        sys.exit(0 if success else 1)

    elif command == "markdown":
        content = sys.argv[2] if len(sys.argv) > 2 else "测试消息"
        title = sys.argv[3] if len(sys.argv) > 3 else "通知"
        success = send_webhook(content, title, "markdown")
        sys.exit(0 if success else 1)

    elif command == "api":
        if len(sys.argv) < 4:
            print("错误：api命令需要chat_id和消息参数")
            sys.exit(1)
        chat_id = sys.argv[2]
        message = sys.argv[3]
        success = send_to_chat(chat_id, message)
        sys.exit(0 if success else 1)

    else:
        print(f"未知命令: {command}")
        sys.exit(1)

if __name__ == "__main__":
    main()
